import{_ as e,o as r,c as h,a2 as t}from"./chunks/framework.EUByU7Iq.js";const p=JSON.parse('{"title":"第五章 股份有限公司的设立和组织机构","description":"","frontmatter":{"title":"第五章 股份有限公司的设立和组织机构","date":"2023-12-29T00:00:00.000Z","categories":["法律","公司法"],"tags":["法律","公司法"],"law_version":"2023修订（2023-12-29 公布，2024-07-01 施行）","v1_source":"blogs/CL/第五章：股份有限公司的设立和组织机构.md"},"headers":[],"relativePath":"blogs/CL/diwuzhang：gufenyouxiangongsideshelihezuzhijigou.md","filePath":"blogs/CL/第五章：股份有限公司的设立和组织机构.md"}'),o={name:"blogs/CL/diwuzhang：gufenyouxiangongsideshelihezuzhijigou.md"};function i(l,a,n,d,s,c){return r(),h("div",null,[...a[0]||(a[0]=[t('<h1 id="第五章-股份有限公司的设立和组织机构" tabindex="-1">第五章 股份有限公司的设立和组织机构 <a class="header-anchor" href="#第五章-股份有限公司的设立和组织机构" aria-label="Permalink to &quot;第五章 股份有限公司的设立和组织机构&quot;">​</a></h1><h3 id="第九十一条" tabindex="-1">第九十一条 <a class="header-anchor" href="#第九十一条" aria-label="Permalink to &quot;第九十一条&quot;">​</a></h3><p>一条设立股份有限公司，可以采取发起设立或者募集设立的方式。 发起设立，是指由发起人认购设立公司时应发行的全部股份而设立公司。 募集设立，是指由发起人认购设立公司时应发行股份的一部分，其余股份向特定对象募集或者向社会公开募集而设立公司。</p><h3 id="第九十二条" tabindex="-1">第九十二条 <a class="header-anchor" href="#第九十二条" aria-label="Permalink to &quot;第九十二条&quot;">​</a></h3><p>二条设立股份有限公司，应当有一人以上二百人以下为发起人，其中应当有半数以上的发起人在中华人民共和国境内有住所。</p><h3 id="第九十三条" tabindex="-1">第九十三条 <a class="header-anchor" href="#第九十三条" aria-label="Permalink to &quot;第九十三条&quot;">​</a></h3><p>三条股份有限公司发起人承担公司筹办事务。 发起人应当签订发起人协议，明确各自在公司设立过程中的权利和义务。</p><h3 id="第九十四条" tabindex="-1">第九十四条 <a class="header-anchor" href="#第九十四条" aria-label="Permalink to &quot;第九十四条&quot;">​</a></h3><p>四条设立股份有限公司，应当由发起人共同制订公司章程。</p><h3 id="第九十五条" tabindex="-1">第九十五条 <a class="header-anchor" href="#第九十五条" aria-label="Permalink to &quot;第九十五条&quot;">​</a></h3><p>五条股份有限公司章程应当载明下列事项： （一）公司名称和住所； （二）公司经营范围； （三）公司设立方式； （四）公司注册资本、已发行的股份数和设立时发行的股份数，面额股的每股金额； （五）发行类别股的，每一类别股的股份数及其权利和义务； （六）发起人的姓名或者名称、认购的股份数、出资方式； （七）董事会的组成、职权和议事规则； （八）公司法定代表人的产生、变更办法； （九）监事会的组成、职权和议事规则； （十）公司利润分配办法； （十一）公司的解散事由与清算办法； （十二）公司的通知和公告办法； （十三）股东会认为需要规定的其他事项。</p><h3 id="第九十六条" tabindex="-1">第九十六条 <a class="header-anchor" href="#第九十六条" aria-label="Permalink to &quot;第九十六条&quot;">​</a></h3><p>六条股份有限公司的注册资本为在公司登记机关登记的已发行股份的股本总额。在发起人认购的股份缴足前，不得向他人募集股份。 法律、行政法规以及国务院决定对股份有限公司注册资本最低限额另有规定的，从其规定。</p><h3 id="第九十七条" tabindex="-1">第九十七条 <a class="header-anchor" href="#第九十七条" aria-label="Permalink to &quot;第九十七条&quot;">​</a></h3><p>七条以发起设立方式设立股份有限公司的，发起人应当认足公司章程规定的公司设立时应发行的股份。 以募集设立方式设立股份有限公司的，发起人认购的股份不得少于公司章程规定的公司设立时应发行股份总数的百分之三十五；但是，法律、行政法规另有规定的，从其规定。</p><h3 id="第九十八条" tabindex="-1">第九十八条 <a class="header-anchor" href="#第九十八条" aria-label="Permalink to &quot;第九十八条&quot;">​</a></h3><p>八条发起人应当在公司成立前按照其认购的股份全额缴纳股款。 发起人的出资，适用本法第四十八条、第四十九条第二款关于有限责任公司股东出资的规定。</p><h3 id="第九十九条" tabindex="-1">第九十九条 <a class="header-anchor" href="#第九十九条" aria-label="Permalink to &quot;第九十九条&quot;">​</a></h3><p>九条发起人不按照其认购的股份缴纳股款，或者作为出资的非货币财产的实际价额显著低于所认购的股份的，其他发起人与该发起人在出资不足的范围内承担连带责任。</p><h3 id="第一百条" tabindex="-1">第一百条 <a class="header-anchor" href="#第一百条" aria-label="Permalink to &quot;第一百条&quot;">​</a></h3><p>百条发起人向社会公开募集股份，应当公告招股说明书，并制作认股书。认股书应当载明本法第一百五十四条第二款、第三款所列事项，由认股人填写认购的股份数、金额、住所，并签名或者盖章。认股人应当按照所认购股份足额缴纳股款。</p><h3 id="第一百零一条" tabindex="-1">第一百零一条 <a class="header-anchor" href="#第一百零一条" aria-label="Permalink to &quot;第一百零一条&quot;">​</a></h3><p>一条向社会公开募集股份的股款缴足后，应当经依法设立的验资机构验资并出具证明。</p><h3 id="第一百零二条" tabindex="-1">第一百零二条 <a class="header-anchor" href="#第一百零二条" aria-label="Permalink to &quot;第一百零二条&quot;">​</a></h3><p>二条股份有限公司应当制作股东名册并置备于公司。股东名册应当记载下列事项： （一）股东的姓名或者名称及住所； （二）各股东所认购的股份种类及股份数； （三）发行纸面形式的股票的，股票的编号； （四）各股东取得股份的日期。</p><h3 id="第一百零三条" tabindex="-1">第一百零三条 <a class="header-anchor" href="#第一百零三条" aria-label="Permalink to &quot;第一百零三条&quot;">​</a></h3><p>三条募集设立股份有限公司的发起人应当自公司设立时应发行股份的股款缴足之日起三十日内召开公司成立大会。发起人应当在成立大会召开十五日前将会议日期通知各认股人或者予以公告。成立大会应当有持有表决权过半数的认股人出席，方可举行。 以发起设立方式设立股份有限公司成立大会的召开和表决程序由公司章程或者发起人协议规定。</p><h3 id="第一百零四条" tabindex="-1">第一百零四条 <a class="header-anchor" href="#第一百零四条" aria-label="Permalink to &quot;第一百零四条&quot;">​</a></h3><p>四条公司成立大会行使下列职权： （一）审议发起人关于公司筹办情况的报告； （二）通过公司章程； （三）选举董事、监事； （四）对公司的设立费用进行审核； （五）对发起人非货币财产出资的作价进行审核； （六）发生不可抗力或者经营条件发生重大变化直接影响公司设立的，可以作出不设立公司的决议。 成立大会对前款所列事项作出决议，应当经出席会议的认股人所持表决权过半数通过。</p><h3 id="第一百零五条" tabindex="-1">第一百零五条 <a class="header-anchor" href="#第一百零五条" aria-label="Permalink to &quot;第一百零五条&quot;">​</a></h3><p>五条公司设立时应发行的股份未募足，或者发行股份的股款缴足后，发起人在三十日内未召开成立大会的，认股人可以按照所缴股款并加算银行同期存款利息，要求发起人返还。 发起人、认股人缴纳股款或者交付非货币财产出资后，除未按期募足股份、发起人未按期召开成立大会或者成立大会决议不设立公司的情形外，不得抽回其股本。</p><h3 id="第一百零六条" tabindex="-1">第一百零六条 <a class="header-anchor" href="#第一百零六条" aria-label="Permalink to &quot;第一百零六条&quot;">​</a></h3><p>六条董事会应当授权代表，于公司成立大会结束后三十日内向公司登记机关申请设立登记。</p><h3 id="第一百零七条" tabindex="-1">第一百零七条 <a class="header-anchor" href="#第一百零七条" aria-label="Permalink to &quot;第一百零七条&quot;">​</a></h3><p>七条本法第四十四条、第四十九条第三款、第五十一条、第五十二条、第五十三条的规定，适用于股份有限公司。</p><h3 id="第一百零八条" tabindex="-1">第一百零八条 <a class="header-anchor" href="#第一百零八条" aria-label="Permalink to &quot;第一百零八条&quot;">​</a></h3><p>八条有限责任公司变更为股份有限公司时，折合的实收股本总额不得高于公司净资产额。有限责任公司变更为股份有限公司，为增加注册资本公开发行股份时，应当依法办理。</p><h3 id="第一百零九条" tabindex="-1">第一百零九条 <a class="header-anchor" href="#第一百零九条" aria-label="Permalink to &quot;第一百零九条&quot;">​</a></h3><p>九条股份有限公司应当将公司章程、股东名册、股东会会议记录、董事会会议记录、监事会会议记录、财务会计报告、债券持有人名册置备于本公司。</p><h3 id="第一百一十条" tabindex="-1">第一百一十条 <a class="header-anchor" href="#第一百一十条" aria-label="Permalink to &quot;第一百一十条&quot;">​</a></h3><p>十条股东有权查阅、复制公司章程、股东名册、股东会会议记录、董事会会议决议、监事会会议决议、财务会计报告，对公司的经营提出建议或者质询。 连续一百八十日以上单独或者合计持有公司百分之三以上股份的股东要求查阅公司的会计账簿、会计凭证的，适用本法第五十七条第二款、第三款、第四款的规定。公司章程对持股比例有较低规定的，从其规定。 股东要求查阅、复制公司全资子公司相关材料的，适用前两款的规定。 上市公司股东查阅、复制相关材料的，应当遵守《中华人民共和国证券法》等法律、行政法规的规定。 第二节股东会</p><h3 id="第一百一十一条" tabindex="-1">第一百一十一条 <a class="header-anchor" href="#第一百一十一条" aria-label="Permalink to &quot;第一百一十一条&quot;">​</a></h3><p>一条股份有限公司股东会由全体股东组成。股东会是公司的权力机构，依照本法行使职权。</p><h3 id="第一百一十二条" tabindex="-1">第一百一十二条 <a class="header-anchor" href="#第一百一十二条" aria-label="Permalink to &quot;第一百一十二条&quot;">​</a></h3><p>二条本法第五十九条第一款、第二款关于有限责任公司股东会职权的规定，适用于股份有限公司股东会。 本法第六十条关于只有一个股东的有限责任公司不设股东会的规定，适用于只有一个股东的股份有限公司。</p><h3 id="第一百一十三条" tabindex="-1">第一百一十三条 <a class="header-anchor" href="#第一百一十三条" aria-label="Permalink to &quot;第一百一十三条&quot;">​</a></h3><p>三条股东会应当每年召开一次年会。有下列情形之一的，应当在两个月内召开临时股东会会议： （一）董事人数不足本法规定人数或者公司章程所定人数的三分之二时； （二）公司未弥补的亏损达股本总额三分之一时； （三）单独或者合计持有公司百分之十以上股份的股东请求时； （四）董事会认为必要时； （五）监事会提议召开时； （六）公司章程规定的其他情形。</p><h3 id="第一百一十四条" tabindex="-1">第一百一十四条 <a class="header-anchor" href="#第一百一十四条" aria-label="Permalink to &quot;第一百一十四条&quot;">​</a></h3><p>四条股东会会议由董事会召集，董事长主持；董事长不能履行职务或者不履行职务的，由副董事长主持；副董事长不能履行职务或者不履行职务的，由过半数的董事共同推举一名董事主持。 董事会不能履行或者不履行召集股东会会议职责的，监事会应当及时召集和主持；监事会不召集和主持的，连续九十日以上单独或者合计持有公司百分之十以上股份的股东可以自行召集和主持。 单独或者合计持有公司百分之十以上股份的股东请求召开临时股东会会议的，董事会、监事会应当在收到请求之日起十日内作出是否召开临时股东会会议的决定，并书面答复股东。</p><h3 id="第一百一十五条" tabindex="-1">第一百一十五条 <a class="header-anchor" href="#第一百一十五条" aria-label="Permalink to &quot;第一百一十五条&quot;">​</a></h3><p>五条召开股东会会议，应当将会议召开的时间、地点和审议的事项于会议召开二十日前通知各股东；临时股东会会议应当于会议召开十五日前通知各股东。 单独或者合计持有公司百分之一以上股份的股东，可以在股东会会议召开十日前提出临时提案并书面提交董事会。临时提案应当有明确议题和具体决议事项。董事会应当在收到提案后二日内通知其他股东，并将该临时提案提交股东会审议；但临时提案违反法律、行政法规或者公司章程的规定，或者不属于股东会职权范围的除外。公司不得提高提出临时提案股东的持股比例。 公开发行股份的公司，应当以公告方式作出前两款规定的通知。 股东会不得对通知中未列明的事项作出决议。</p><h3 id="第一百一十六条" tabindex="-1">第一百一十六条 <a class="header-anchor" href="#第一百一十六条" aria-label="Permalink to &quot;第一百一十六条&quot;">​</a></h3><p>六条股东出席股东会会议，所持每一股份有一表决权，类别股股东除外。公司持有的本公司股份没有表决权。 股东会作出决议，应当经出席会议的股东所持表决权过半数通过。 股东会作出修改公司章程、增加或者减少注册资本的决议，以及公司合并、分立、解散或者变更公司形式的决议，应当经出席会议的股东所持表决权的三分之二以上通过。</p><h3 id="第一百一十七条" tabindex="-1">第一百一十七条 <a class="header-anchor" href="#第一百一十七条" aria-label="Permalink to &quot;第一百一十七条&quot;">​</a></h3><p>七条股东会选举董事、监事，可以按照公司章程的规定或者股东会的决议，实行累积投票制。 本法所称累积投票制，是指股东会选举董事或者监事时，每一股份拥有与应选董事或者监事人数相同的表决权，股东拥有的表决权可以集中使用。</p><h3 id="第一百一十八条" tabindex="-1">第一百一十八条 <a class="header-anchor" href="#第一百一十八条" aria-label="Permalink to &quot;第一百一十八条&quot;">​</a></h3><p>八条股东委托代理人出席股东会会议的，应当明确代理人代理的事项、权限和期限；代理人应当向公司提交股东授权委托书，并在授权范围内行使表决权。</p><h3 id="第一百一十九条" tabindex="-1">第一百一十九条 <a class="header-anchor" href="#第一百一十九条" aria-label="Permalink to &quot;第一百一十九条&quot;">​</a></h3><p>九条股东会应当对所议事项的决定作成会议记录，主持人、出席会议的董事应当在会议记录上签名。会议记录应当与出席股东的签名册及代理出席的委托书一并保存。 第三节董事会、经理</p><h3 id="第一百二十条" tabindex="-1">第一百二十条 <a class="header-anchor" href="#第一百二十条" aria-label="Permalink to &quot;第一百二十条&quot;">​</a></h3><p>十条股份有限公司设董事会，本法第一百二十八条另有规定的除外。 本法第六十七条、第六十八条第一款、第七十条、第七十一条的规定，适用于股份有限公司。</p><h3 id="第一百二十一条" tabindex="-1">第一百二十一条 <a class="header-anchor" href="#第一百二十一条" aria-label="Permalink to &quot;第一百二十一条&quot;">​</a></h3><p>一条股份有限公司可以按照公司章程的规定在董事会中设置由董事组成的审计委员会，行使本法规定的监事会的职权，不设监事会或者监事。 审计委员会成员为三名以上，过半数成员不得在公司担任除董事以外的其他职务，且不得与公司存在任何可能影响其独立客观判断的关系。公司董事会成员中的职工代表可以成为审计委员会成员。 审计委员会作出决议，应当经审计委员会成员的过半数通过。 审计委员会决议的表决，应当一人一票。 审计委员会的议事方式和表决程序，除本法有规定的外，由公司章程规定。 公司可以按照公司章程的规定在董事会中设置其他委员会。</p><h3 id="第一百二十二条" tabindex="-1">第一百二十二条 <a class="header-anchor" href="#第一百二十二条" aria-label="Permalink to &quot;第一百二十二条&quot;">​</a></h3><p>二条董事会设董事长一人，可以设副董事长。董事长和副董事长由董事会以全体董事的过半数选举产生。 董事长召集和主持董事会会议，检查董事会决议的实施情况。副董事长协助董事长工作，董事长不能履行职务或者不履行职务的，由副董事长履行职务；副董事长不能履行职务或者不履行职务的，由过半数的董事共同推举一名董事履行职务。</p><h3 id="第一百二十三条" tabindex="-1">第一百二十三条 <a class="header-anchor" href="#第一百二十三条" aria-label="Permalink to &quot;第一百二十三条&quot;">​</a></h3><p>三条董事会每年度至少召开两次会议，每次会议应当于会议召开十日前通知全体董事和监事。 代表十分之一以上表决权的股东、三分之一以上董事或者监事会，可以提议召开临时董事会会议。董事长应当自接到提议后十日内，召集和主持董事会会议。 董事会召开临时会议，可以另定召集董事会的通知方式和通知时限。</p><h3 id="第一百二十四条" tabindex="-1">第一百二十四条 <a class="header-anchor" href="#第一百二十四条" aria-label="Permalink to &quot;第一百二十四条&quot;">​</a></h3><p>四条董事会会议应当有过半数的董事出席方可举行。董事会作出决议，应当经全体董事的过半数通过。 董事会决议的表决，应当一人一票。 董事会应当对所议事项的决定作成会议记录，出席会议的董事应当在会议记录上签名。</p><h3 id="第一百二十五条" tabindex="-1">第一百二十五条 <a class="header-anchor" href="#第一百二十五条" aria-label="Permalink to &quot;第一百二十五条&quot;">​</a></h3><p>五条董事会会议，应当由董事本人出席；董事因故不能出席，可以书面委托其他董事代为出席，委托书应当载明授权范围。 董事应当对董事会的决议承担责任。董事会的决议违反法律、行政法规或者公司章程、股东会决议，给公司造成严重损失的，参与决议的董事对公司负赔偿责任；经证明在表决时曾表明异议并记载于会议记录的，该董事可以免除责任。</p><h3 id="第一百二十六条" tabindex="-1">第一百二十六条 <a class="header-anchor" href="#第一百二十六条" aria-label="Permalink to &quot;第一百二十六条&quot;">​</a></h3><p>六条股份有限公司设经理，由董事会决定聘任或者解聘。 经理对董事会负责，根据公司章程的规定或者董事会的授权行使职权。经理列席董事会会议。</p><h3 id="第一百二十七条" tabindex="-1">第一百二十七条 <a class="header-anchor" href="#第一百二十七条" aria-label="Permalink to &quot;第一百二十七条&quot;">​</a></h3><p>七条公司董事会可以决定由董事会成员兼任经理。</p><h3 id="第一百二十八条" tabindex="-1">第一百二十八条 <a class="header-anchor" href="#第一百二十八条" aria-label="Permalink to &quot;第一百二十八条&quot;">​</a></h3><p>八条规模较小或者股东人数较少的股份有限公司，可以不设董事会，设一名董事，行使本法规定的董事会的职权。该董事可以兼任公司经理。</p><h3 id="第一百二十九条" tabindex="-1">第一百二十九条 <a class="header-anchor" href="#第一百二十九条" aria-label="Permalink to &quot;第一百二十九条&quot;">​</a></h3><p>九条公司应当定期向股东披露董事、监事、高级管理人员从公司获得报酬的情况。 第四节监事会</p><h3 id="第一百三十条" tabindex="-1">第一百三十条 <a class="header-anchor" href="#第一百三十条" aria-label="Permalink to &quot;第一百三十条&quot;">​</a></h3><p>十条股份有限公司设监事会，本法第一百二十一条第一款、第一百三十三条另有规定的除外。 监事会成员为三人以上。监事会成员应当包括股东代表和适当比例的公司职工代表，其中职工代表的比例不得低于三分之一，具体比例由公司章程规定。监事会中的职工代表由公司职工通过职工代表大会、职工大会或者其他形式民主选举产生。 监事会设主席一人，可以设副主席。监事会主席和副主席由全体监事过半数选举产生。监事会主席召集和主持监事会会议；监事会主席不能履行职务或者不履行职务的，由监事会副主席召集和主持监事会会议；监事会副主席不能履行职务或者不履行职务的，由过半数的监事共同推举一名监事召集和主持监事会会议。 董事、高级管理人员不得兼任监事。 本法第七十七条关于有限责任公司监事任期的规定，适用于股份有限公司监事。</p><h3 id="第一百三十一条" tabindex="-1">第一百三十一条 <a class="header-anchor" href="#第一百三十一条" aria-label="Permalink to &quot;第一百三十一条&quot;">​</a></h3><p>一条本法第七十八条至第八十条的规定，适用于股份有限公司监事会。 监事会行使职权所必需的费用，由公司承担。</p><h3 id="第一百三十二条" tabindex="-1">第一百三十二条 <a class="header-anchor" href="#第一百三十二条" aria-label="Permalink to &quot;第一百三十二条&quot;">​</a></h3><p>二条监事会每六个月至少召开一次会议。监事可以提议召开临时监事会会议。 监事会的议事方式和表决程序，除本法有规定的外，由公司章程规定。 监事会决议应当经全体监事的过半数通过。 监事会决议的表决，应当一人一票。 监事会应当对所议事项的决定作成会议记录，出席会议的监事应当在会议记录上签名。</p><h3 id="第一百三十三条" tabindex="-1">第一百三十三条 <a class="header-anchor" href="#第一百三十三条" aria-label="Permalink to &quot;第一百三十三条&quot;">​</a></h3><p>三条规模较小或者股东人数较少的股份有限公司，可以不设监事会，设一名监事，行使本法规定的监事会的职权。 第五节上市公司组织机构的特别规定</p><h3 id="第一百三十四条" tabindex="-1">第一百三十四条 <a class="header-anchor" href="#第一百三十四条" aria-label="Permalink to &quot;第一百三十四条&quot;">​</a></h3><p>四条本法所称上市公司，是指其股票在证券交易所上市交易的股份有限公司。</p><h3 id="第一百三十五条" tabindex="-1">第一百三十五条 <a class="header-anchor" href="#第一百三十五条" aria-label="Permalink to &quot;第一百三十五条&quot;">​</a></h3><p>五条上市公司在一年内购买、出售重大资产或者向他人提供担保的金额超过公司资产总额百分之三十的，应当由股东会作出决议，并经出席会议的股东所持表决权的三分之二以上通过。</p><h3 id="第一百三十六条" tabindex="-1">第一百三十六条 <a class="header-anchor" href="#第一百三十六条" aria-label="Permalink to &quot;第一百三十六条&quot;">​</a></h3><p>六条上市公司设独立董事，具体管理办法由国务院证券监督管理机构规定。 上市公司的公司章程除载明本法第九十五条规定的事项外，还应当依照法律、行政法规的规定载明董事会专门委员会的组成、职权以及董事、监事、高级管理人员薪酬考核机制等事项。</p><h3 id="第一百三十七条" tabindex="-1">第一百三十七条 <a class="header-anchor" href="#第一百三十七条" aria-label="Permalink to &quot;第一百三十七条&quot;">​</a></h3><p>七条上市公司在董事会中设置审计委员会的，董事会对下列事项作出决议前应当经审计委员会全体成员过半数通过： （一）聘用、解聘承办公司审计业务的会计师事务所； （二）聘任、解聘财务负责人； （三）披露财务会计报告； （四）国务院证券监督管理机构规定的其他事项。</p><h3 id="第一百三十八条" tabindex="-1">第一百三十八条 <a class="header-anchor" href="#第一百三十八条" aria-label="Permalink to &quot;第一百三十八条&quot;">​</a></h3><p>八条上市公司设董事会秘书，负责公司股东会和董事会会议的筹备、文件保管以及公司股东资料的管理，办理信息披露事务等事宜。</p><h3 id="第一百三十九条" tabindex="-1">第一百三十九条 <a class="header-anchor" href="#第一百三十九条" aria-label="Permalink to &quot;第一百三十九条&quot;">​</a></h3><p>九条上市公司董事与董事会会议决议事项所涉及的企业或者个人有关联关系的，该董事应当及时向董事会书面报告。有关联关系的董事不得对该项决议行使表决权，也不得代理其他董事行使表决权。该董事会会议由过半数的无关联关系董事出席即可举行，董事会会议所作决议须经无关联关系董事过半数通过。出席董事会会议的无关联关系董事人数不足三人的，应当将该事项提交上市公司股东会审议。</p><h3 id="第一百四十条" tabindex="-1">第一百四十条 <a class="header-anchor" href="#第一百四十条" aria-label="Permalink to &quot;第一百四十条&quot;">​</a></h3><p>十条上市公司应当依法披露股东、实际控制人的信息，相关信息应当真实、准确、完整。 禁止违反法律、行政法规的规定代持上市公司股票。</p><h3 id="第一百四十一条" tabindex="-1">第一百四十一条 <a class="header-anchor" href="#第一百四十一条" aria-label="Permalink to &quot;第一百四十一条&quot;">​</a></h3><p>一条上市公司控股子公司不得取得该上市公司的股份。 上市公司控股子公司因公司合并、质权行使等原因持有上市公司股份的，不得行使所持股份对应的表决权，并应当及时处分相关上市公司股份。</p><hr><p class="law-foot">本篇依据《中华人民共和国公司法》2023 年 12 月 29 日第十四届全国人大常委会第七次会议第二次修订文本，自 2024 年 7 月 1 日起施行；本站同步于 2026-11-07。</p>',105)])])}const b=e(o,[["render",i]]);export{p as __pageData,b as default};
